{
  "decision-reconcile-independent-carton-witnesses": "WITH witnesses AS (SELECT n.carton_code, n.desk_code, MIN(n.note_id) AS note_id FROM carton_note AS n WHERE n.finding = 'absent' AND NOT EXISTS (SELECT 1 FROM carton_note AS p WHERE p.carton_code = n.carton_code AND p.finding = 'present') GROUP BY n.carton_code, n.desk_code), ranked AS (SELECT carton_code, note_id, ROW_NUMBER() OVER (PARTITION BY carton_code ORDER BY desk_code) AS desk_rank FROM witnesses) SELECT carton_code, COUNT(*) AS witness_count, MAX(CASE WHEN desk_rank = 1 THEN note_id END) AS first_note, MAX(CASE WHEN desk_rank = 2 THEN note_id END) AS second_note FROM ranked GROUP BY carton_code HAVING COUNT(*) >= 2 ORDER BY carton_code",
  "decision-reconcile-return-crates-by-model": "WITH contributions AS (SELECT batch_code, model_code, crate_qty AS expected, 0 AS counted FROM return_plan UNION ALL SELECT u.batch_code, u.model_code, 0, COALESCE(u.crate_qty, 0) FROM unload_line AS u WHERE u.batch_code IN (SELECT batch_code FROM return_plan)), totals AS (SELECT batch_code, model_code, SUM(expected) AS expected_qty, SUM(counted) AS counted_qty FROM contributions GROUP BY batch_code, model_code) SELECT batch_code, model_code, expected_qty, counted_qty, counted_qty - expected_qty AS variance_qty FROM totals WHERE counted_qty <> expected_qty ORDER BY batch_code, model_code",
  "decision-reconcile-split-fifo-lots": "WITH adjusted AS (SELECT lot_id, acquired_on, CASE WHEN acquired_on < '2026-04-10' THEN acquired_shares / 2 * 3 ELSE acquired_shares END AS shares FROM stock_lots), inventory AS (SELECT adjusted.*, SUM(shares) OVER (ORDER BY acquired_on, lot_id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_shares FROM adjusted) SELECT lot_id, MIN(shares, MAX(0, cumulative_shares - sold_shares)) AS remaining_shares FROM inventory CROSS JOIN stock_sale ORDER BY acquired_on, lot_id",
  "decision-reconcile-transferred-finish-credits": "WITH contributions AS (SELECT ticket_id, lane_id, award_pts AS delta, slip_ref FROM finish_slips UNION ALL SELECT j.ticket_id, j.lane_id, -j.movement_pts, s.slip_ref FROM posting_journal AS j JOIN finish_slips AS s ON s.ticket_id = j.ticket_id) SELECT ticket_id, lane_id, SUM(delta) AS adjustment_pts, slip_ref FROM contributions GROUP BY ticket_id, lane_id, slip_ref HAVING SUM(delta) <> 0 ORDER BY ticket_id, lane_id"
}
